    const k = f >= 2 ? 'pend2' : 'pend1', v = await uiDialog({ icon: LT_IC[k], title: lt(k, 't'), html: lt(k, 'h'), buttons: [{ t: 'VOLVER', v: 0 }, { t: 'COMPROBAR AHORA', cls: 'ok', v: 1 }] });
