/* ---------- botón ✕ para salir del juego (portada y mapas) ---------- */
(() => {
  const st = document.createElement('style'); st.textContent = `
#btnExit{position:fixed;top:12px;right:12px;top:calc(12px + env(safe-area-inset-top, 0px));right:calc(12px + env(safe-area-inset-right, 0px));left:auto;bottom:auto;margin:0;z-index:12;min-width:42px;min-height:42px;box-sizing:border-box;width:42px;height:42px;padding:0;border-radius:50%;font:900 20px system-ui;line-height:1;display:none;align-items:center;justify-content:center;border-color:#ff4a6a;box-shadow:0 0 14px rgba(255,74,106,.55);color:#fff;touch-action:manipulation}
#btnExit.on{display:flex}
#byeOv{position:fixed;inset:0;z-index:90;display:none;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:radial-gradient(ellipse at 50% 40%,#0b1a4a,#010309 75%);color:#cfe0ff;text-align:center;font-family:system-ui,sans-serif;padding:20px}
#byeOv.on{display:flex}
#byeOv img{width:min(70vw,460px);filter:drop-shadow(0 0 16px rgba(53,255,138,.45))}
#byeOv h2{margin:0;color:#35ff8a;letter-spacing:.12em;text-shadow:0 0 12px #35ff8a}`;
  document.head.appendChild(st);
  const b = document.createElement('button'); b.id = 'btnExit'; b.className = 'btn'; b.innerHTML = SVG_X; b.title = 'Salir del juego'; document.body.appendChild(b);
  const bye = document.createElement('div'); bye.id = 'byeOv';
  const logo = document.querySelector('#title .logo'); bye.innerHTML = (logo ? '<img src="' + logo.getAttribute('src') + '" alt="">' : '') + '<h2>¡HASTA PRONTO!</h2><div>Tu progreso está guardado.<br>Este navegador no deja que el juego se cierre solo: ciérralo desde las pestañas o deslizando la app.</div><button class="btn" id="byeBack" style="opacity:.6;font-size:12px">VOLVER</button>';
  document.body.appendChild(bye);
  const vis = () => { const on = !CON.on && !$('adm').classList.contains('on') && !bye.classList.contains('on') && !$('uidlg').classList.contains('on') && ((state === 'title' && $('title').classList.contains('on') && !$('panel').classList.contains('on')) || (state === 'map' && !warp && !$('panel').classList.contains('on'))); b.classList.toggle('on', on); };
  setInterval(vis, 200);
  let busy = false;
  tapBind(b, async () => { if (busy) return; busy = true;
    const ok = await uiConfirm('¿SALIR DEL JUEGO?', 'Se cerrará COSMOLUCAS. Tu progreso queda guardado.', 'SALIR', 'CANCELAR', '<img src="img/puerta-salir.webp" alt="" style="height:clamp(70px,16vh,120px);filter:drop-shadow(0 0 14px rgba(53,255,138,.45))">'); busy = false; if (!ok) return;
    try { cloudSave(true); } catch (e) {} try { if (AC) AC.suspend(); } catch (e) {}
    const appInst = (() => { try { return matchMedia('(display-mode: fullscreen)').matches || matchMedia('(display-mode: standalone)').matches || navigator.standalone === true; } catch (e) { return false; } })();
    try { window.close(); } catch (e) {}          // app instalada: se cierra del todo
    setTimeout(() => { if (document.hidden) return; try { window.open('', '_self'); window.close(); } catch (e) {}
    setTimeout(() => { if (document.hidden) return; if (!appInst && history.length > 1) { try { history.back(); } catch (e) {} }      // si se abrió desde otra página, se sale del juego hacia atrás
      setTimeout(() => { if (!document.hidden) { bye.classList.add('on'); b.classList.remove('on'); } }, 600); }, 300); }, 150);      // si el navegador no deja cerrar la pestaña, pantalla de despedida      // si el navegador no deja cerrar (pestaña normal, iPhone), se queda la pantalla de despedida
  });
  $('byeBack').onclick = () => { bye.classList.remove('on'); try { audio(); } catch (e) {} };
})();
