  antena: { n: 'antena', img: 'obj-antena5g', h: 48 }, poster: { n: 'póster', img: 'adv-poster', h: 50 }, huevo: { n: 'huevo', img: 'huevo-1', h: 44 }, laser: { n: 'pila de láser', img: 'obj-laser', h: 42 },
